export function UserRow({user}:{user:User}){const name=displayName(user);return <tr className={user.active?"user-row":"user-row user-row--inactive"} style={{opacity:user.active?1:0.5}}><td><Avatar name={name}/>{name}{!user.active&&<small> (nieaktywny)</small>}</td><td>{user.login}</td><td><RoleBadge role={user.role}/></td><td>{user.active?"Aktywny":"Nieaktywny"}</td></tr>;}
export function UserTable({users}:{users:readonly User[]}){if(users.length===0)return <p>Brak użytkowników</p>;return <table><thead><tr><th scope="col">Użytkownik</th><th scope="col">Login</th><th scope="col">Rola</th><th scope="col">Status</th></tr></thead><tbody>{users.map(user=><UserRow key={user.id} user={user}/>)}</tbody></table>;}
export function UsersPage({users,onInvite}:{users:readonly User[];onInvite:()=>void}){return <main><h1>Użytkownicy</h1><Panel title="Statystyki"><StatsRow users={users}/></Panel><Panel title="Lista użytkowników" actions={<button type="button" onClick={onInvite}>+Zaproś</button>}><UserTable users={users}/></Panel></main>;}
export function ActiveUsers({users}:{users:readonly User[]}){return <UserTable users={users.filter(user=>user.active)}/>;}

import type {ReactNode} from "react";
type Role="admin"|"agent"|"viewer";
type User={id:number;login:string;name:string|null;role:Role;active:boolean};
export function displayName(user:User):string{return user.name??user.login;}
export function initials(name:string):string{return name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]?.toUpperCase()??"").join("");}
export function summarize(users:readonly User[]){return {total:users.length,active:users.filter(user=>user.active).length,admins:users.filter(user=>user.role==="admin").length};}
